-- WHERE NOT EXISTS evita que a política de conflito de um UPSERT externo sobrescreva OR IGNORE dos triggers.
ALTER TABLE projection_state ADD COLUMN last_duration_ms INTEGER NOT NULL DEFAULT 0;
ALTER TABLE projection_state ADD COLUMN updated_at TEXT;
-- A fila registra inclusive exclusões e alterações feitas fora dos importadores.
CREATE TABLE projection_changes(kind TEXT NOT NULL,record_key TEXT NOT NULL,PRIMARY KEY(kind,record_key)) WITHOUT ROWID;
CREATE INDEX idx_projection_event ON conexoes_rede(tipo_relacao,COALESCE(json_extract(metadata_json,'$.receita_id'),json_extract(metadata_json,'$.despesa_id'),json_extract(metadata_json,'$.contrato_id'))) WHERE json_extract(metadata_json,'$.projection')='radar';
DROP TRIGGER IF EXISTS projection_dirty_politicos_insert;
CREATE TRIGGER projection_dirty_politicos_insert AFTER INSERT ON politicos BEGIN UPDATE projection_state SET dirty=1 WHERE id=1 AND dirty=0; UPDATE auditoria_estado SET pendente=1 WHERE id=1 AND pendente=0; INSERT INTO projection_changes SELECT 'politico',CAST(NEW.id AS TEXT) WHERE NOT EXISTS(SELECT 1 FROM projection_changes WHERE kind='politico' AND record_key=CAST(NEW.id AS TEXT)); INSERT INTO projection_changes SELECT 'ceap',CAST(id AS TEXT) FROM despesas_parlamentares WHERE (parlamentar_nome IN (NEW.nome_completo,NEW.nome_urna)) AND NOT EXISTS(SELECT 1 FROM projection_changes WHERE kind='ceap' AND record_key=CAST(id AS TEXT)); END;
