-- A projeção v2 íntegra é compatível; só as entidades colocadas em quarentena mudaram.
UPDATE projection_state SET version=3,dirty=EXISTS(SELECT 1 FROM projection_changes) WHERE version=2 AND EXISTS(SELECT 1 FROM projection_upgrade_state WHERE version=2 AND dirty=0);
